;----------------------------------------------------------------------
; Hi-res text — Mode 5 assets (original procedural art)
;
; text.pic: deduplicated 8x8 subtiles emitted in left/right pairs
; (Mode 5's 16x8 tiles read character N and N+1); text.map: 64x32
; entries pointing at the even indices; 4-color palette. Generated by
; the script in the example README; committed like the wavetable /
; hicolor precedents so builds don't depend on Pillow.
;----------------------------------------------------------------------

.section ".rodata1" superfree

text_pic:       .incbin "res/text.pic"
text_pic_end:

text_map:       .incbin "res/text.map"
text_map_end:

text_pal:       .incbin "res/text.pal"
text_pal_end:

.ends
